pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market to initialize the contract
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Get a non-CEO account and give it some ether
        address nonCeo = address(0x1234);
        vm.deal(nonCeo, 1 ether);

        // Non-CEO calls DrugDealer
        vm.prank(nonCeo);
        c.DrugDealer();

        // Now call sellDrugs from nonCeo – this transfers devFee to ceoAddress
        // First, give nonCeo some kilos (otherwise sell reverts because getMyDrugs() == 0)
        vm.prank(nonCeo);
        c.getFreeKilo();
        // Warp forward 86401 seconds so getMyDrugs() > 0
        vm.warp(block.timestamp + 86401);

        // Try sellDrugs from nonCeo; if ceoAddress == address(this) (original contract's ceo after DrugDealer),
        // the transfer to ceoAddress will fail because address(this) cannot receive Ether (it's a contract with no receive).
        // If ceoAddress == address(0) (buggy version), the transfer to address(0) succeeds silently.
        // We assert that the call reverts for the reference (ceoAddress == nonCeo, a non-payable EOA but still fails because address(this) is the contract itself).
        // Actually, after DrugDealer, reference ceoAddress = nonCeo (an EOA), bug ceoAddress = address(0).
        // We'll transfer via sellDrugs; for reference, devFee goes to nonCeo (works). For bug, goes to address(0) (works).
        // To force a revert difference, we need better setup: after DrugDealer, both reference and bug ceo are not the contract.
        // Let's adjust: have the original ceo address be this contract (address(this)) which has no receive.
        // But contract C's ceoAddress is hardcoded to 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26. We cannot change that.
        // Instead, use the fact that after DrugDealer reassigns ceoAddress, we can call collectDrugs with a high referral.
        // Actually, simpler: after DrugDealer, both versions have ceoAddress changed (ref to nonCeo, bug to 0).
        // Then call buyDrugs with a small amount – the devFee(msg.value) is sent to ceoAddress.
        // For reference, it goes to nonCeo (works). For bug, to address(0) (works). So no revert difference.
        // Need a different approach: make ceoAddress the contract itself after DrugDealer, so transfer reverts.
        // But the reference sets ceoAddress = msg.sender, which is nonCeo, so no revert there either.
        // Actually, in the reference, the original ceoAddress is 0x85ab..., which can receive ether.
        // After DrugDealer, it becomes nonCeo, which can receive. The bug becomes address(0), which also receives.
        // The only difference: if we call DrugDealer with the contract itself as sender... but msg.sender would be address(this) (the test contract), which is different from the constant address.
        // Both would change ceoAddress to address(this) or 0 respectively – both can receive Ether (test contract has a receive? not defined, but by default it can receive? Actually solidity contracts can receive if they have payable fallback. Forge test inherits Test which has a receive? Not sure. Safer: avoid ether transfer to ceoAddress.
        // Use collectDrugs: it modifies claimedDrugs[referrals[msg.sender]] which depends on ceoAddress? No.
        // SellDrugs also transfers to ceoAddress. 
        // Let's instead compare ceoAddress after the call: one is nonCeo, other is 0.
        // We can just read ceoAddress() after DrugDealer from a non-CEO and assert that it equals nonCeo (reference) vs equals 0 (bug). That's a direct observation.
        // But the instruction says "assertTrue(<concrete fact reading c>)". So:
        vm.prank(nonCeo);
        c.DrugDealer();
        // For reference, ceoAddress == nonCeo; for bug, ceoAddress == 0.
        address expectedCeo = nonCeo; // reference behavior
        assertTrue(c.ceoAddress() == nonCeo); // passes on reference, fails on bug because bug ceo is 0
    }
}

