contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: seed market and give CEO some Ether and kilos to enable sellDrugs
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.deal(ceo, 1 ether);
        vm.startPrank(ceo);
        c.seedMarket{value: 1 ether}(1000);
        c.getFreeKilo();
        // Let some time pass so getMyDrugs returns > 0
        vm.warp(block.timestamp + 86400);
        // Call DrugDealer: CEO calls it, reference keeps ceoAddress = ceo, bug sets to address(0)
        c.DrugDealer();
        vm.stopPrank();
        // Now try to sell drugs as CEO; if ceoAddress is address(0), transfer reverts
        vm.prank(ceo);
        try c.sellDrugs() {
            // If it succeeded, the buggy version (transfer to address(0) reverted) should not reach here
            assertTrue(address(c).balance > 0); // dummy; won't matter
        } catch {
            revert("Bug: sellDrugs reverted");
        }
        // If we reach here, the reference passed (sellDrugs succeeded)
        assertTrue(true); // placeholder to satisfy compiler, but actually we already passed
    }
}

