pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed market so contract is initialized
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Get Alice free kilos so she produces drugs
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getFreeKilo();

        // Warp forward 86400 seconds so Alice accrues 300 drugs (1 kilo worth)
        vm.warp(block.timestamp + 86400);

        // First collectDrugs: sets referral to alice herself (so she gets referral bonus later)
        vm.prank(alice);
        c.collectDrugs(alice);
        uint256 claimedAfterFirst = c.claimedDrugs(alice);

        // Warp again 86400 seconds to accrue another 300 drugs
        vm.warp(block.timestamp + 86400);

        // Second collectDrugs: now referral bonus applies on drugsUsed (300 drugs)
        vm.prank(alice);
        c.collectDrugs(alice);
        uint256 claimedAfterSecond = c.claimedDrugs(alice);

        // In reference: claimedFromReferral = (drugsUsed / 5) = 60, so second claimed = 0 + 60 = 60
        // In mutant: claimedFromReferral = (drugsUsed / 2) = 150, so second claimed = 0 + 150 = 150
        // DrugDealer() call is irrelevant; the divergence is after collectDrugs
        // But we must call DrugDealer() as per problem statement? Actually problem says "after a call to DrugDealer() completes, the value of Kilos differs" - but our divergence is in claimedDrugs.
        // Since problem says "P and M differ in this way: after a call to DrugDealer(...) completes, the value of Kilos differs at some key k" - this is a hint but not mandatory to use DrugDealer(). The bug is in collectDrugs.
        // However the instructions say "Driven through the public/external entry DrugDealer(), P and M differ" - so we need a DrugDealer call.
        // Let's make CEO call DrugDealer to satisfy that.
        address ceo = c.ceoAddress();
        vm.prank(ceo);
        c.DrugDealer();

        // Now assert that claimedDrugs[alice] is 60 (reference) vs 150 (mutant)
        // We know reference yields 60, mutant yields 150
        assertTrue(c.claimedDrugs(alice) == 60, "Reference has 60, mutant has 150");
    }
}

