pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market with 1000 drugs (any positive value) to initialize
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        vm.deal(ceo, 1 ether);
        vm.prank(ceo);
        c.seedMarket(1000);

        // Get free kilos for Alice (so she produces drugs over time)
        address alice = address(0x1234);
        vm.prank(alice);
        c.getFreeKilo();

        // Warp forward 86400 seconds to produce 1 kilo of drugs per kilo owned
        // Alice has 300 kilos, so after 86400 seconds she accumulates 300*86400 drugs
        vm.warp(block.timestamp + 86400);

        // First collectDrugs: Alice calls with ref = address(0) (no referral set yet)
        vm.prank(alice);
        c.collectDrugs(address(0));

        // Warp another 86400 seconds to accumulate more drugs
        vm.warp(block.timestamp + 86400);

        // Second collectDrugs: Now Alice has a referral (the earlier call set referral to address(0))
        // The referral bonus is calculated on the drugsUsed
        vm.prank(alice);
        c.collectDrugs(address(0));

        // After second collectDrugs, claimedDrugs[address(0)] differs:
        // Reference: claimedDrugs[referral] += drugsUsed / 5 (drugsUsed ≈ 300*86400)
        // Mutant: claimedDrugs[referral] += drugsUsed / 2
        uint256 claimedInReference = c.claimedDrugs(address(0));
        // The reference should have drugsUsed/5, but we just check that the mutant result is larger
        // For the concrete test, we assert that claimedDrugs[address(0)] is exactly what the reference computes
        // We know: drugsUsed = 300*86400 = 25920000, /5 = 5184000, /2 = 12960000
        // So reference yields 5184000, mutant yields 12960000
        // The concrete assertion: claimedDrugs[address(0)] equals 5184000
        assertTrue(c.claimedDrugs(address(0)) == 5184000);
    }
}

