import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market so contract is initialized
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Alice gets free kilos to start accumulating drugs
        address alice = address(0xABCD);
        vm.prank(alice);
        c.getFreeKilo();

        // Warp forward 86400 seconds so she has 300 drugs from kilos
        vm.warp(block.timestamp + 86400);

        // First collectDrugs: sets referral to self (since referrals[alice]==address(0) && referrals[alice]!=alice)
        // This transfers 300 drugs into kilos (300/86400 = 0 kilos), resets claimedDrugs[alice]=0,
        // and adds referral bonus: under reference 300/5=60, under mutant 300/2=150 to claimedDrugs[alice]
        vm.prank(alice);
        c.collectDrugs(address(0)); // ref = address(0) but gets replaced with self in the if

        // Warp another 86400 seconds to accumulate more drugs from kilos (still 300 kilos * 86400 sec = 300 drugs)
        vm.warp(block.timestamp + 86400);

        // Second collectDrugs: now referrals[alice] = alice, so referral bonus goes to alice again
        // drugsUsed = claimedDrugs[alice] (60 or 150 from before) + 300 from kilos = 360 or 450
        // New kilos added from drugsUsed: 360/86400=0 or 450/86400=0
        // Then claimedDrugs[alice] is reset to 0
        // Then referral bonus added: reference 360/5=72, mutant 450/2=225
        // So final claimedDrugs[alice] after second call: reference = 72, mutant = 225
        vm.prank(alice);
        c.collectDrugs(address(0)); // ref doesn't matter, referral is already set to alice

        // Assert: under reference, claimedDrugs[alice] should be exactly 72
        // Under mutant, it will be 225, so assertion fails on buggy version
        assertTrue(c.claimedDrugs(alice) == 72, "claimedDrugs mismatch");
    }
}

