pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Seed the market to initialize the contract
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Step 2: Alice gets free kilos so she produces drugs over time
        address alice = address(0x123);
        vm.prank(alice);
        c.getFreeKilo();

        // Step 3: Warp time to produce exactly 86400 drugs (since DRUGS_TO_PRODUCE_1KILO = 86400 and she has 300 kilos)
        // We need secondsPassed * 300 >= 86400, so secondsPassed >= 288. Let's use 288 seconds.
        vm.warp(block.timestamp + 288);

        // Step 4: First collectDrugs with referral to herself
        vm.prank(alice);
        c.collectDrugs(alice);  // This sets referrals[alice]=alice and produces some kilos

        // Now Alice has claimedDrugs[alice] = 0 after first collect, and new kilos added
        // But we need more drugs for a second collect. Warp more time.
        vm.warp(block.timestamp + 288);

        // Step 5: Second collectDrugs; this will trigger the referral bonus to herself
        vm.prank(alice);
        c.collectDrugs(alice);  // During this call, referral bonus is added

        // The difference: claimedDrugs[alice] after second collect
        // Reference: referral bonus = drugsUsed / 5, but drugsUsed is getMyDrugs() at call time
        // Mutant: referral bonus = drugsUsed / 2
        // After the call, claimedDrugs[alice] was reset to 0 and then the referral bonus is added,
        // but because the referral is herself, the referral bonus goes to her claimedDrugs.
        // Also, after the second collect, claimedDrugs[msg.sender] is set to 0,
        // BUT then claimedDrugs[referrals[msg.sender]] = claimedDrugs[alice] gets the bonus.
        // However, note that the order: first claimedDrugs[msg.sender]=0, then claimedDrugs[referrals[...]]+=bonus.
        // So after call, claimedDrugs[alice] = bonus.
        // In reference, bonus = drugsUsed/5; in mutant, bonus = drugsUsed/2.

        // We compute expected reference value for the scenario:
        // drugsUsed = getMyDrugs() at time of second collect = claimedDrugs[alice](0) + getDrugsSinceLastCollect
        // After first collect, lastCollect was set to block.timestamp before the warp.
        // Actually we warped after first collect, so secondsPassed = 288.
        // getDrugsSinceLastCollect = min(86400, 288) * 300 = 288 * 300 = 86400.
        // So drugsUsed = 0 + 86400 = 86400.
        // Reference bonus = 86400/5 = 17280.
        // Mutant bonus = 86400/2 = 43200.
        // So claimedDrugs[alice] after second collect should be 17280 in reference, 43200 in mutant.

        uint256 claimed = c.claimedDrugs(alice);
        // Assert that the value is the reference value (17280). If mutant is 43200, this fails.
        assertTrue(claimed == 17280, "claimedDrugs mismatch");
    }
}

