        c.DrugDealer();

        // After DrugDealer, we observe marketDrugs – both versions should have same value
        // Actually the mutation is in collectDrugs, so the value was already different after collectDrugs
        // Let's check that the reference version's marketDrugs after collectDrugs is consistent
