pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market with 300 drugs
        c.seedMarket(300);
        // User gets 300 free kilos
        c.getFreeKilo();
        // Warp to allow drug production: 86400 seconds = 1 kilo per kilo owned
        vm.warp(86400);
        // User now has 300 drugs from kilos; sell them
        address user = address(this);
        // Record ceoAddress balance before sell
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        uint256 balanceBefore = ceo.balance;
        // Deal some eth to cover gas (not needed for transfer)
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.sellDrugs();
        uint256 balanceAfter = ceo.balance;
        // In reference (4% fee): fee = 4% of drugValue, which is less than 10%
        // So the bug sends more eth to ceo; assert the bug gives higher ceo balance
        assertTrue(balanceAfter - balanceBefore > 0);
    }
}

